#pragma once

static const char JRBOT_WEB_V1_HTML[]=
"<!doctype html><html lang='pt-br'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>JrBot V1</title><style>"
":root{color-scheme:dark;--bg:#09111e;--card:#132036;--line:#29415f;--text:#f5f8ff;--muted:#9fb1ca;--a:#5ea7ff;--b:#896eff;--ok:#63d99b;--bad:#ff8585}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#0c1b35,#09111e 300px);color:var(--text);font:15px system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:820px;margin:auto;padding:20px 14px 46px}.top{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:17px}h1{margin:0;font-size:28px}.sub{color:var(--muted);font-size:13px}.pill{border:1px solid var(--line);border-radius:99px;padding:7px 10px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--bad);margin-right:6px}.dot.ok{background:var(--ok)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.stat,.card{background:var(--card);border:1px solid var(--line);border-radius:16px}.stat{padding:12px}.stat small{display:block;color:var(--muted);margin-bottom:4px}.card{padding:16px;margin:11px 0}.card h2{font-size:17px;margin:0 0 13px}.faces{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}button,a.action,label.action{border:1px solid var(--line);background:#1a2a43;color:var(--text);border-radius:11px;padding:11px 12px;font:inherit;cursor:pointer;text-decoration:none;text-align:center}.primary{background:linear-gradient(135deg,var(--a),var(--b));border-color:#7394ff;font-weight:650}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.grow{flex:1}.hint{color:var(--muted);font-size:12px;line-height:1.4;margin-top:8px}.state{color:var(--muted);font-size:13px;margin-top:9px}select{background:#1a2a43;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px}input[type=range]{width:100%}input[type=file]{display:none}audio{width:100%;margin-top:11px}.camera{width:100%;aspect-ratio:4/3;object-fit:contain;background:#05090f;border:1px solid var(--line);border-radius:13px;margin-bottom:10px}.feedback{min-height:20px;color:var(--muted);font-size:13px;margin:15px 2px}.feedback.err{color:var(--bad)}.foot{color:var(--muted);font-size:12px;border-top:1px solid var(--line);padding-top:13px;margin-top:20px}@media(max-width:600px){main{padding:14px 10px 36px}.grid{grid-template-columns:1fr 1fr}.faces{grid-template-columns:repeat(2,1fr)}button,a.action,label.action{min-height:45px}.card{padding:14px}}"
"</style></head><body><main>"
"<div class='top'><div><h1>JrBot</h1><div class='sub'>V1 · painel local · JrBot_V1.4.1</div></div><div class='pill sub'><span id='dot' class='dot'></span><span id='conn'>Conectando</span></div></div>"
"<div class='grid'><div class='stat'><small>Face</small><b id='face'>—</b></div><div class='stat'><small>Volume</small><b id='volume'>—</b></div><div class='stat'><small>Microfone</small><b id='mic'>—</b></div><div class='stat'><small>Wi-Fi</small><b id='wifi'>—</b></div><div class='stat'><small>IP</small><b id='ip'>—</b></div><div class='stat'><small>Firmware</small><b id='fw'>—</b></div></div>"
"<section class='card'><div class='row'><span class='grow'><b>Consulta automática de status</b><div class='hint'>Quando desligada, o App não consulta /status a cada 10 segundos.</div></span><button id='auto-status' class='primary'>SIM</button></div></section>"
"<section class='card'><h2>Rosto</h2><div id='faces-main' class='faces'></div><details><summary>Mais expressões</summary><div id='faces-more' class='faces' style='margin-top:9px'></div></details></section>"
"<section class='card'><h2>Câmera</h2><img id='camera' class='camera' alt='Câmera do JrBot' hidden><div class='row'><button id='cam-btn' class='primary grow'>Capturar foto</button><a id='cam-save' class='action grow' download='jrbot-camera.jpg' hidden>Salvar foto</a></div><div class='hint'>Captura sob demanda da OV5640.</div></section>"
"<section class='card'><h2>Mensagem do celular</h2><div class='row'><button id='phone-record' class='primary grow'>Gravar mensagem</button><button id='phone-file' class='grow'>Escolher áudio</button></div><input id='audio-file' type='file' accept='.wav,.mp3,.m4a,.mp4'><audio id='phone-player' controls hidden></audio><div id='phone-actions' class='row' style='margin-top:10px' hidden><button id='phone-play-jrbot' class='primary grow'>Tocar no JrBot</button><button id='phone-rerecord' class='grow'>Gravar novamente</button></div><div id='phone-state' class='state'>Grave uma mensagem de voz no celular e depois toque no JrBot.</div><div class='hint'>A gravação direta usa somente o microfone. Se o navegador bloquear o microfone nesta conexão, use Escolher áudio. O áudio é convertido para WAV PCM 16-bit, mono, 16 kHz, máximo de 10 segundos.</div></section>"
"<section class='card'><h2>Microfone do JrBot</h2><div class='row'><label>Gravar</label><select id='seconds'><option value='1'>1 s</option><option value='3' selected>3 s</option><option value='5'>5 s</option><option value='10'>10 s</option></select><button id='record' class='primary'>Gravar áudio</button></div><audio id='player' controls hidden></audio><div id='record-actions' class='row' style='margin-top:10px' hidden><a id='download' class='action grow'>Baixar WAV</a><button id='play-recording' class='grow'>Tocar no JrBot</button></div></section>"
"<section class='card'><h2>Som</h2><div class='row'><span>Volume</span><b id='vol-label'>35</b></div><input id='vol' type='range' min='0' max='100' value='35'><div class='row' style='margin-top:12px'><button id='apply-volume' class='primary grow'>Aplicar volume</button><button id='test-sound' class='grow'>Testar som</button></div></section>"
"<div id='feedback' class='feedback'>Pronto.</div><div class='foot'>Controle local do JrBot. Sem autenticação/TLS: use somente na rede local confiável.</div>"
"<script>const q=i=>document.getElementById(i),mf=[['neutro','Neutro'],['feliz','Feliz'],['pensando','Pensando'],['surpreso','Surpreso'],['triste','Triste'],['sono','Sono'],['amor','Amor'],['cool','Cool']],xf=[['animado','Animado'],['bravo','Bravo'],['cetico','Cético'],['confuso','Confuso'],['piscando','Piscando'],['brincalhao','Brincalhão'],['preocupado','Preocupado'],['bateria','Bateria']];let busy=false,recUrl=null,camUrl=null,phoneUrl=null,phoneWav=null,phoneRecorder=null,phoneStream=null,phoneChunks=[],phoneTimer=null;let autoStatus=true;function fb(t,e=false){q('feedback').textContent=t;q('feedback').className='feedback'+(e?' err':'')}function faces(id,a){for(const f of a){const b=document.createElement('button');b.textContent=f[1];b.onclick=()=>cmd(f[0],'Face: '+f[1]);q(id).appendChild(b)}}faces('faces-main',mf);faces('faces-more',xf);async function send(c){const r=await fetch('/cmd',{method:'POST',headers:{'Content-Type':'text/plain','X-JrBot-Command':'1'},body:c}),t=await r.text();if(!r.ok)throw Error(t);return t}async function cmd(c,m){if(busy)return;busy=true;try{await send(c);fb(m);await status(true)}catch(e){fb('Erro: '+e.message,true)}finally{busy=false}}"
"function ascii(v,o,s){for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))}function wavBlob(samples,rate){const buf=new ArrayBuffer(44+samples.length*2),v=new DataView(buf);ascii(v,0,'RIFF');v.setUint32(4,36+samples.length*2,true);ascii(v,8,'WAVE');ascii(v,12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,rate,true);v.setUint32(28,rate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);ascii(v,36,'data');v.setUint32(40,samples.length*2,true);let o=44;for(let i=0;i<samples.length;i++,o+=2){let x=Math.max(-1,Math.min(1,samples[i]));v.setInt16(o,x<0?x*32768:x*32767,true)}return new Blob([buf],{type:'audio/wav'})}"
"async function convertAudio(file){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Este navegador não consegue converter áudio.');const ctx=new AC(),ab=await file.arrayBuffer();let decoded;try{decoded=await ctx.decodeAudioData(ab.slice(0))}finally{try{await ctx.close()}catch(_){}}if(!decoded||!decoded.length)throw Error('Áudio vazio ou formato não suportado.');if(decoded.duration>10.0)throw Error('A mensagem deve ter no máximo 10 segundos.');const rate=16000,count=Math.max(1,Math.floor(decoded.length*rate/decoded.sampleRate)),out=new Float32Array(count),chs=[];for(let c=0;c<decoded.numberOfChannels;c++)chs.push(decoded.getChannelData(c));const ratio=decoded.sampleRate/rate;for(let i=0;i<count;i++){const p=i*ratio,a=Math.floor(p),b=Math.min(a+1,decoded.length-1),f=p-a;let s=0;for(const ch of chs)s+=ch[a]+(ch[b]-ch[a])*f;out[i]=s/chs.length}return wavBlob(out,rate)}"
"async function preparePhoneAudio(file){if(!file||busy)return;busy=true;q('phone-state').textContent='Preparando mensagem...';try{const wav=await convertAudio(file);phoneWav=wav;if(phoneUrl)URL.revokeObjectURL(phoneUrl);phoneUrl=URL.createObjectURL(wav);q('phone-player').src=phoneUrl;q('phone-player').hidden=false;q('phone-actions').hidden=false;q('phone-state').textContent='Mensagem pronta. Ouça e toque no JrBot quando quiser.';fb('Mensagem do celular pronta.')}catch(e){phoneWav=null;q('phone-actions').hidden=true;q('phone-player').hidden=true;q('phone-state').textContent='Não foi possível preparar a mensagem.';fb('Erro no áudio: '+e.message,true)}finally{busy=false;q('audio-file').value=''}}"
"function releasePhoneStream(){if(phoneTimer){clearTimeout(phoneTimer);phoneTimer=null}if(phoneStream){for(const t of phoneStream.getTracks())t.stop();phoneStream=null}}async function togglePhoneRecord(){if(phoneRecorder&&phoneRecorder.state==='recording'){phoneRecorder.stop();return}if(busy)return;if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){q('phone-state').textContent='Gravação direta indisponível neste navegador ou nesta conexão. Use Escolher áudio.';fb('O navegador não liberou gravação direta pelo microfone.',true);return}busy=true;try{phoneStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});phoneChunks=[];phoneRecorder=new MediaRecorder(phoneStream);phoneRecorder.ondataavailable=e=>{if(e.data&&e.data.size)phoneChunks.push(e.data)};phoneRecorder.onstop=async()=>{const type=phoneRecorder&&phoneRecorder.mimeType?phoneRecorder.mimeType:'audio/mp4',blob=new Blob(phoneChunks,{type});releasePhoneStream();phoneRecorder=null;q('phone-record').textContent='Gravar mensagem';busy=false;await preparePhoneAudio(blob)};phoneRecorder.onerror=()=>{releasePhoneStream();phoneRecorder=null;q('phone-record').textContent='Gravar mensagem';busy=false;q('phone-state').textContent='Falha ao gravar pelo microfone.';fb('Falha ao gravar pelo microfone.',true)};phoneRecorder.start();q('phone-record').textContent='Parar gravação';q('phone-state').textContent='Gravando pelo microfone do celular... máximo 10 segundos.';fb('Gravando mensagem no celular.');phoneTimer=setTimeout(()=>{if(phoneRecorder&&phoneRecorder.state==='recording')phoneRecorder.stop()},10000)}catch(e){releasePhoneStream();phoneRecorder=null;q('phone-record').textContent='Gravar mensagem';q('phone-state').textContent=window.isSecureContext?'Não foi possível acessar o microfone. Verifique a permissão.':'O navegador bloqueou o microfone nesta conexão HTTP. Use Escolher áudio.';fb('Microfone do celular indisponível: '+e.message,true);busy=false}}"
"async function playPhoneAudio(){if(!phoneWav||busy)return;busy=true;try{q('phone-state').textContent='Enviando para o JrBot...';const r=await fetch('/audio',{method:'POST',headers:{'Content-Type':'audio/wav','X-JrBot-Audio':'1'},body:phoneWav}),t=await r.text();if(!r.ok)throw Error(t);q('phone-state').textContent='Mensagem tocada no JrBot.';fb('Mensagem reproduzida no JrBot.')}catch(e){q('phone-state').textContent='Falha ao tocar no JrBot.';fb('Erro no áudio: '+e.message,true)}finally{busy=false}}"
"async function camera(){if(busy)return;busy=true;try{fb('Capturando foto...');const r=await fetch('/capture?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();if(camUrl)URL.revokeObjectURL(camUrl);camUrl=URL.createObjectURL(b);q('camera').src=camUrl;q('camera').hidden=false;q('cam-save').href=camUrl;q('cam-save').hidden=false;q('cam-btn').textContent='Atualizar foto';fb('Foto atualizada.')}catch(e){fb('Erro na câmera: '+e.message,true)}finally{busy=false}}"
"async function record(){if(busy)return;busy=true;try{fb('Gravando...');const r=await fetch('/mic-record?seconds='+q('seconds').value,{cache:'no-store'});if(!r.ok)throw Error(await r.text());const b=await r.blob();if(recUrl)URL.revokeObjectURL(recUrl);recUrl=URL.createObjectURL(b);q('player').src=recUrl;q('player').hidden=false;q('download').href=recUrl;q('download').download='jrbot-microfone.wav';q('record-actions').hidden=false;fb('Gravação concluída.')}catch(e){fb('Erro na gravação: '+e.message,true)}finally{busy=false;await status(true)}}"
"function parse(t){const o={};for(const p of t.trim().split(' ')){const i=p.indexOf('=');if(i>0)o[p.slice(0,i)]=p.slice(i+1)}return o}async function status(force=false){if(busy&&!force)return;try{const r=await fetch('/status',{cache:'no-store'}),s=parse(await r.text());if(!r.ok)throw Error('status');q('dot').className='dot ok';q('conn').textContent='Online';q('face').textContent=s.expression||'—';q('volume').textContent=(s.volume||'—')+(s.volume?'%':'');q('mic').textContent=s.mic||'—';q('wifi').textContent=s.wifi==='1'?'Conectado':'Desconectado';q('ip').textContent=s.ip||'—';q('fw').textContent=s.version||'—';if(s.volume){q('vol').value=s.volume;q('vol-label').textContent=s.volume}}catch(e){q('dot').className='dot';q('conn').textContent='Offline'}}"
"q('auto-status').onclick=()=>{autoStatus=!autoStatus;q('auto-status').textContent=autoStatus?'SIM':'NÃO';q('auto-status').className=autoStatus?'primary':'';fb('Consulta automática de status: '+(autoStatus?'ativada':'desativada'));};q('cam-btn').onclick=camera;q('phone-record').onclick=togglePhoneRecord;q('phone-file').onclick=()=>q('audio-file').click();q('phone-rerecord').onclick=togglePhoneRecord;q('phone-play-jrbot').onclick=playPhoneAudio;q('audio-file').onchange=e=>preparePhoneAudio(e.target.files[0]);q('record').onclick=record;q('play-recording').onclick=()=>cmd('audio_play_recording','Reproduzindo gravação');q('apply-volume').onclick=()=>cmd('audio_volume '+q('vol').value,'Volume ajustado');q('test-sound').onclick=()=>cmd('audio_test','Teste de som enviado');q('vol').oninput=()=>q('vol-label').textContent=q('vol').value;status();setInterval(()=>{if(autoStatus)status(false)},10000);</script>"
"</main></body></html>";
